// Clean flight delay data by setting any negative component values to NULL
def delayFields = ["CARRIER_DELAY", "WEATHER_DELAY", "NAS_DELAY", "SECURITY_DELAY", "LATE_AIRCRAFT_DELAY"]
delayFields.each { field ->
    def val = record.getValue(field)
    if (val != null && ((Number) val).doubleValue() < 0) {
        record.setValue(field, null)
    }
}

return record
